descriptor.templateCss:
.rpm-control-root {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  font-family: Roboto, Arial, sans-serif;
  color: #172033;
  background: #ffffff;
}

.rpm-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.rpm-value {
  font-size: 27px;
  font-weight: 700;
  line-height: 1;
}

.rpm-unit {
  font-size: 17px;
  font-weight: 600;
}

.rpm-status {
  min-width: 72px;
  text-align: right;
  font-size: 13px;
  font-weight: 600;
  color: #64748b;
}

.rpm-range {
  width: 100%;
  cursor: pointer;
  accent-color: #4f64ff;
}

.rpm-scale {
  display: flex;
  justify-content: space-between;
  color: #64748b;
  font-size: 12px;
  margin-top: -5px;
}

.rpm-input-row {
  display: grid;
  grid-template-columns: auto minmax(100px, 150px) auto;
  align-items: center;
  gap: 10px;
}

.rpm-input-row label {
  font-size: 14px;
  font-weight: 600;
}

.rpm-number {
  box-sizing: border-box;
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
}

.rpm-apply {
  height: 36px;
  padding: 0 18px;
  border: 0;
  border-radius: 6px;
  color: #ffffff;
  background: #3657f6;
  font-weight: 700;
  cursor: pointer;
}

.rpm-apply:disabled,
.rpm-range:disabled,
.rpm-number:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rpm-note {
  font-size: 12px;
  color: #64748b;
}

@media (max-width: 600px) {
  .rpm-input-row {
    grid-template-columns: 1fr auto;
  }
  .rpm-input-row label {
    grid-column: 1 / -1;
  }
}

descriptor.controllerScript:
self.onInit = function() {
    const settings = Object.assign({
        minRpm: 0,
        maxRpm: 3200,
        stepRpm: 100,
        initialRpm: 800,
        requestTimeout: 5000,
        getMethod: 'getManualFanRpm',
        setMethod: 'setFanRpm'
    }, self.ctx.settings || {});

    const root = self.ctx.$container[0];
    const range = root.querySelector('.rpm-range');
    const number = root.querySelector('.rpm-number');
    const valueNumber = root.querySelector('.rpm-value-number');
    const status = root.querySelector('.rpm-status');
    const apply = root.querySelector('.rpm-apply');
    const minLabel = root.querySelector('.rpm-min');
    const maxLabel = root.querySelector('.rpm-max');

    const minRpm = Number(settings.minRpm);
    const maxRpm = Number(settings.maxRpm);
    const stepRpm = Math.max(1, Number(settings.stepRpm));
    let confirmedValue = normalize(settings.initialRpm);
    let requestInProgress = false;

    range.min = String(minRpm);
    range.max = String(maxRpm);
    range.step = String(stepRpm);
    number.min = String(minRpm);
    number.max = String(maxRpm);
    number.step = String(stepRpm);
    minLabel.textContent = minRpm + ' RPM';
    maxLabel.textContent = maxRpm + ' RPM';

    function normalize(value) {
        let numeric = Number(value);
        if (!Number.isFinite(numeric)) {
            numeric = Number(settings.initialRpm) || 800;
        }
        numeric = Math.max(minRpm, Math.min(maxRpm, numeric));
        numeric = Math.round((numeric - minRpm) / stepRpm) * stepRpm + minRpm;
        return Math.max(minRpm, Math.min(maxRpm, numeric));
    }

    function extractRpm(response) {
        if (typeof response === 'number' || typeof response === 'string') {
            return normalize(response);
        }
        if (response && response.fan_rpm !== undefined) {
            return normalize(response.fan_rpm);
        }
        if (response && response.value !== undefined) {
            return normalize(response.value);
        }
        if (response && response.state && response.state.fan_rpm_manual_setpoint !== undefined) {
            return normalize(response.state.fan_rpm_manual_setpoint);
        }
        return confirmedValue;
    }

    function showValue(value) {
        const normalized = normalize(value);
        range.value = String(normalized);
        number.value = String(normalized);
        valueNumber.textContent = String(normalized);
        return normalized;
    }

    function setBusy(busy, message) {
        requestInProgress = busy;
        range.disabled = busy;
        number.disabled = busy;
        apply.disabled = busy;
        status.textContent = message;
    }

    function sendSetpoint(rawValue) {
        if (requestInProgress) {
            return;
        }
        const requestedValue = showValue(rawValue);
        setBusy(true, 'Sending…');
        self.ctx.controlApi.sendTwoWayCommand(
            settings.setMethod,
            requestedValue,
            Number(settings.requestTimeout)
        ).subscribe(
            function success(response) {
                confirmedValue = extractRpm(response);
                showValue(confirmedValue);
                setBusy(false, 'Applied');
            },
            function failure() {
                showValue(confirmedValue);
                setBusy(false, 'RPC failed');
            }
        );
    }

    function requestCurrentSetpoint() {
        setBusy(true, 'Reading…');
        self.ctx.controlApi.sendTwoWayCommand(
            settings.getMethod,
            {},
            Number(settings.requestTimeout)
        ).subscribe(
            function success(response) {
                confirmedValue = extractRpm(response);
                showValue(confirmedValue);
                setBusy(false, 'Ready');
            },
            function failure() {
                confirmedValue = showValue(settings.initialRpm);
                setBusy(false, 'Using default');
            }
        );
    }

    range.addEventListener('input', function() {
        showValue(range.value);
        status.textContent = 'Not applied';
    });

    range.addEventListener('change', function() {
        sendSetpoint(range.value);
    });

    number.addEventListener('input', function() {
        if (number.value !== '') {
            showValue(number.value);
            status.textContent = 'Not applied';
        }
    });

    number.addEventListener('keydown', function(event) {
        if (event.key === 'Enter') {
            event.preventDefault();
            sendSetpoint(number.value);
        }
    });

    apply.addEventListener('click', function() {
        sendSetpoint(number.value);
    });

    showValue(confirmedValue);
    requestCurrentSetpoint();
};

self.onResize = function() {};
self.onDestroy = function() {};
